IF OBJECT_ID('dbo.NotificationLog','U') IS NOT NULL DROP TABLE dbo.NotificationLog; IF OBJECT_ID('dbo.RechargeHistory','U') IS NOT NULL DROP TABLE dbo.RechargeHistory; IF OBJECT_ID('dbo.Subscribers','U') IS NOT NULL DROP TABLE dbo.Subscribers;
CREATE TABLE dbo.Subscribers(SubscriberID int PRIMARY KEY,SubscriberName nvarchar(100),PhoneMasked varchar(20),SubscriberType varchar(10),Balance decimal(10,2),PlanID int,ValidityEnd date); CREATE TABLE dbo.RechargeHistory(RechargeID int IDENTITY PRIMARY KEY,SubscriberID int REFERENCES dbo.Subscribers,Amount decimal(10,2),RechargeDate datetime2 DEFAULT SYSDATETIME(),PlanID int); CREATE TABLE dbo.NotificationLog(NotificationID int IDENTITY PRIMARY KEY,SubscriberID int,Message nvarchar(200),CreatedAt datetime2 DEFAULT SYSDATETIME(),IsRead bit DEFAULT 0);
